/**
 * docs/NUMBERS.md cannot drift. It is generated by scripts/docs/numbers.ts from the code, the recorded fixtures and the
 * committed results; these tests compare it with a fresh measurement. If one fails, regenerate and commit:
 *   npx tsx scripts/docs/numbers.ts --write      (about a minute: it also runs the unit tests and the "Worth it?" search)
 *
 * What `npm test` recomputes (a few seconds) is every "fast" block. The slow blocks (3.2, 3.3 and 6.1) are guarded by
 * hashes recorded in the file: one over everything they depend on, one over the tables as committed. The unit-test and
 * e2e counts cannot be recomputed from inside a test run, so adding or removing a test (or spec) trips the inputs hash.
 * `npx tsx scripts/docs/numbers.ts --check` recomputes every block, slow ones included. The units ledger lives in the
 * gitignored internal/LEDGER.md and is compared only where that file can be found.
 */
import { readFileSync } from "node:fs";
import { beforeAll, describe, expect, test } from "vitest";
import { extractBlock } from "../../scripts/docs/blocks";
import { DOC_PATH, SECTIONS, buildSections, findLedger, fingerprintBody, type Built } from "../../scripts/docs/numbers";

const REGENERATE = "run npx tsx scripts/docs/numbers.ts --write and commit docs/NUMBERS.md";

let doc = "";
let fresh: Built[] = [];

beforeAll(async () => {
  doc = readFileSync(DOC_PATH, "utf8").replace(/\r\n/g, "\n");
  fresh = await buildSections({ slow: false, previous: doc });
}, 120_000);

describe("docs/NUMBERS.md", () => {
  test("opens with the sentence the README, video and Devpost rely on", () => {
    expect(doc).toContain(
      "Every number quoted in the README, video and Devpost comes from this file. Regenerate with `npx tsx scripts/docs/numbers.ts --write`.",
    );
  });

  for (const def of SECTIONS.filter((s) => s.tier === "fast")) {
    test(`block "${def.id}" matches a fresh measurement`, () => {
      const built = fresh.find((b) => b.id === def.id);
      expect(built, `section ${def.id} was not built`).toBeDefined();
      expect(extractBlock(doc, def.id), `docs/NUMBERS.md block "${def.id}" is stale: ${REGENERATE}`).toBe(built!.body.trim());
    });
  }

  test.skipIf(findLedger() === null)("block \"ledger\" matches internal/LEDGER.md", () => {
    const built = fresh.find((b) => b.id === "ledger");
    expect(extractBlock(doc, "ledger"), `the unit ledger changed: ${REGENERATE}`).toBe(built!.body.trim());
  });

  test("the slow blocks are untouched and their inputs have not changed", () => {
    const slow: Built[] = SECTIONS.filter((s) => s.tier === "slow").map((s) => ({ id: s.id, tier: "slow", body: extractBlock(doc, s.id) }));
    expect(slow.length).toBeGreaterThan(0);
    expect(
      extractBlock(doc, "fingerprint"),
      `lib/, the tests, the e2e specs, the fixtures or the slow tables changed since docs/NUMBERS.md was generated (3.2, 3.3, 6.1 may be stale): ${REGENERATE}`,
    ).toBe(fingerprintBody([...fresh, ...slow]).trim());
  });
});
